int kvm_set_one_core_register(struct kvm_vcpu *vcpu, const struct kvm_one_reg *reg)
{
    int ret = 0;
    unsigned int offset;
    void *dest;
    unsigned long val;

    offset = kvm_reg_offset(reg->id);
    if (offset == KVM_REG_INVALID)
        return -ENOENT;

    if (offset + sizeof(val) > sizeof(vcpu->arch.regs))
        return -EINVAL;

    if (copy_from_user(&val, (void __user *)(unsigned long)reg->addr, sizeof(val)))
        return -EFAULT;

    dest = (void *)((unsigned long)vcpu->arch.regs + offset);

    if (reg->id == KVM_REG_ARM_CORE_REG) {
        if ((val & PSR_MODE_MASK) != PSR_MODE_EL1)
            return -EINVAL;
    }

    *(unsigned long *)dest = val;
    return ret;
}

int kvm_set_one_core_reg(struct kvm_vcpu *vcpu, const struct kvm_one_reg *reg)
{
    int offset, ret;

    if (reg->id < KVM_REG_CORE || reg->id >= KVM_REG_CPU_0 ||
        (reg->id & (KVM_REG_SIZE_MASK | KVM_REG_ARCH_MASK)))
        return -EINVAL;

    offset = (reg->id & KVM_REG_OFFSET_MASK) - KVM_REG_CORE;

    if (offset < 0 || offset >= sizeof(vcpu->arch.regs))
        return -ENOENT;

    if ((offset + (reg->id & KVM_REG_SIZE_MASK)) > sizeof(vcpu->arch.regs))
        return -EFAULT;

    switch (reg->id & KVM_REG_SIZE_MASK) {
    case 1:
        ret = copy_from_user(&vcpu->arch.regs[offset], (void __user *)(unsigned long)reg->addr, 1);
        break;
    case 2:
        ret = copy_from_user(&vcpu->arch.regs[offset], (void __user *)(unsigned long)reg->addr, 2);
        break;
    case 4:
        ret = copy_from_user(&vcpu->arch.regs[offset], (void __user *)(unsigned long)reg->addr, 4);
        break;
    case 8:
        ret = copy_from_user(&vcpu->arch.regs[offset], (void __user *)(unsigned long)reg->addr, 8);
        break;
    default:
        return -EINVAL;
    }

    if (ret)
        return -EFAULT;

    if (offset == offsetof(struct kvm_vcpu, arch.regs[offsetof(struct kvm_regs, cr0)])) {
        if (vcpu->arch.mode != KVM_MODE_PROTECTED &&
            (vcpu->arch.cr0 & X86_CR0_PE))
            return -EINVAL;
    }

    return 0;
}

int kvm_set_one_core_register(struct kvm_vcpu *vcpu, const struct kvm_one_reg *reg) {
    void *gva;
    int r = 0;

    if (reg->id >= KVM_REG_CORE_MAX)
        return -ENOENT;

    gva = guest_virt_to_phys(vcpu, reg->addr);
    if (IS_ERR(gva))
        return PTR_ERR(gva);

    switch (reg->id) {
    case KVM_REG_RIP:
        vcpu->arch.regs[VCPU_REGS_RIP] = *(uint64_t *)gva;
        break;
    case KVM_REG_RSP:
        vcpu->arch.regs[VCPU_REGS_RSP] = *(uint64_t *)gva;
        break;
    case KVM_REG_RFLAGS:
        vcpu->arch.regs[VCPU_REGS_RFLAGS] = *(uint64_t *)gva;
        break;
    default:
        r = -EINVAL;
        break;
    }

    if (reg->id == KVM_REG_RFLAGS) {
        if (vcpu->arch.mode & VM_MODE_PV) {
            if (vcpu->arch.regs[VCPU_REGS_RFLAGS] & (1 << 6))
                r = -EINVAL;
        }
    }

    return r;
}

int kvm_set_one_core_register(struct kvm_vcpu *vcpu, const struct kvm_one_reg *reg)
{
    int ret = 0;
    void *gva;
    size_t offset;

    if (reg->id >= KVM_REG_COUNT)
        return -EINVAL;

    offset = get_core_register_offset(reg->id);
    if (offset == -1)
        return -ENOENT;

    if (offset + sizeof(*gva) > sizeof(vcpu->arch.core_regs))
        return -EINVAL;

    gva = (void *)((char *)&vcpu->arch.core_regs + offset);

    if (copy_from_user(gva, (void __user *)(unsigned long)reg->addr, sizeof(*gva)))
        return -EFAULT;

    if (reg->id == KVM_REG_PSR) {
        unsigned int mode;
        memcpy(&mode, gva, sizeof(mode));
        if (mode & ~kvm_get_supported_modes()) {
            ret = -EINVAL;
        } else {
            vcpu->arch.mode = mode;
        }
    }

    return ret;
}

int kvm_set_one_core_register(struct kvm_vcpu *vcpu, const struct kvm_one_reg *reg)
{
    void *gpr = &vcpu->arch.regs;
    int offset = kvm_register_offset(reg->id);
    int ret = -ENOENT;

    if (offset < 0)
        return -ENOENT;

    if (!kvm_register_is_valid(reg->id))
        return -EINVAL;

    if (reg->addr > KVM_REG_SIZE_LIMIT || (offset + KVM_REG_SIZE_LIMIT) > sizeof(vcpu->arch.regs))
        return -EFAULT;

    if (kvm_is_process_state_register(reg->id)) {
        unsigned long val;
        if (copy_from_user(&val, (void __user *)(unsigned long)reg->addr, sizeof(val)))
            return -EFAULT;

        if (val & ~KVM_PROCESS_STATE_MASK)
            return -EINVAL;

        if (!kvm_cpu_has_system_capability(KVM_CAP_PROCESS_STATE)) {
            if (val != KVM_PROCESS_STATE_DEFAULT)
                return -EINVAL;
        }

        if (vcpu->arch.process_state & KVM_PROCESS_STATE_ACTIVE)
            return -EINVAL;

        vcpu->arch.process_state = val;
    }

    if (copy_from_user(gpr + offset, (void __user *)(unsigned long)reg->addr, sizeof(unsigned long)))
        return -EFAULT;

    return 0;
}
